+const assert = require('assert');
+const Anthropic = require('@anthropic-ai/sdk');
+const fs = require('fs');
+const pkg = JSON.parse(fs.readFileSync('node_modules/@anthropic-ai/sdk/package.json', 'utf8'));
+(async () => {
+  let body, headers;
+  const fetch = async (url, init) => {
+    body = JSON.parse(init.body); headers = new Headers(init.headers);
+    return new Response(JSON.stringify({ id: 'm', type: 'message', role: 'assistant', model: 'x',
+      content: [{ type: 'text', text: '{"iban":"BE68"}' }], stop_reason: 'end_turn', stop_sequence: null,
+      usage: { input_tokens: 1, output_tokens: 1 } }), { headers: { 'content-type': 'application/json' } });
+  };
+  const C = Anthropic.default || Anthropic;
+  const client = new C({ apiKey: 'dummy', fetch });
+  const msg = await client.messages.create({ model: 'claude-sonnet-4-6', max_tokens: 10,
+    messages: [{ role: 'user', content: [{ type: 'text', text: 'hi' }] }] });
+  assert.strictEqual(msg.content[0].text, '{"iban":"BE68"}');
+  for (const k of ['temperature', 'top_p', 'top_k']) assert(!(k in body));
+  assert.strictEqual(headers.get('anthropic-version'), '2026-10-21');
+  assert(pkg.version.startsWith('1.'), pkg.version);
+  // call sites must not set sampling params
+  for (const f of ['server.js', 'api/extract.js']) assert(!/temperature|top_p|top_k/.test(fs.readFileSync(f, 'utf8')));
+  console.log('ok', pkg.version);
+})().catch(e => { console.error(e); process.exit(1); });
